<script lang="ts">
import { defineComponent } from 'vue';
import { notify, errorHistory } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'NotificationTest',
  setup() {
    return { errorHistory };
  },
  methods: {
    triggerSuccess() {
      notify.success('Document exported successfully');
    },
    triggerError() {
      notify.error('Export failed');
    },
    triggerWarning() {
      notify.warning('Rate limit approaching — 85% of API quota used');
    },
    triggerInfo() {
      notify.info('New version available — v2.4.1');
    },
    triggerErrorWithDetail() {
      notify.error(
        'Export failed',
        'Connection timeout after 30s. Server returned ETIMEDOUT at 10.0.1.5:443',
      );
    },
    triggerErrorLongDetail() {
      notify.error(
        'API request failed',
        'Error: Request failed with status code 500\n' +
        'at createError (createError.js:16:15)\n' +
        'at settle (settle.js:17:12)\n' +
        'at XMLHttpRequest.onloadend (xhr.js:66:7)\n' +
        'Correlation-ID: abc-123-def-456',
      );
    },
    triggerShortDuration() {
      notify.info('This disappears quickly', { duration: 1000 });
    },
    triggerPersistent() {
      notify.info('This stays until dismissed', { duration: Infinity });
    },
    triggerSuccessDescription() {
      notify.success('Document saved', { description: 'invoice_2024.pdf has been saved to your downloads folder' });
    },
    triggerWarningDescription() {
      notify.warning('Session expiring soon', { description: 'Your session will expire in 5 minutes. Save your work.' });
    },
    triggerWithAction() {
      notify.info('Item deleted', {
        action: {
          label: 'Undo',
          onClick: () => notify.success('Item restored'),
        },
      });
    },
    triggerBurst3() {
      notify.success('First notification');
      notify.info('Second notification');
      notify.warning('Third notification');
    },
    triggerBurst5() {
      for (let i = 1; i <= 5; i++) {
        notify.info(`Notification ${i} of 5`);
      }
    },
    triggerMixedBurst() {
      notify.success('Upload complete');
      notify.error('Validation failed', 'Missing required field: invoice_number');
      notify.warning('Large file detected');
      notify.info('Processing started');
    },
    triggerAndDismiss() {
      const id = notify.info('This will auto-dismiss in 2 seconds...', { duration: Infinity });
      setTimeout(() => {
        notify.dismiss(id);
        notify.success('Programmatically dismissed!');
      }, 2000);
    },
    dismissAll() {
      notify.dismissAll();
    },
  },
});
</script>

